using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
namespace LucidLoop.CharacterArt
{
 [DefaultExecutionOrder(900)] public sealed class RenDesignerMouthReview:MonoBehaviour
 {
  public RenDesignerForeheadFieldReview Context;public SkinnedMeshRenderer[] Mouth;public float OpenA,Seal=1;public string ImportAuditSha256,RuntimeSha256,BuilderSha256;
  int[] jaw,seal;float ClosedWeight=>1-Mathf.SmoothStep(0,1,Mathf.Clamp01(OpenA/.75f));
  void Awake(){if(Mouth.Length!=4)throw new InvalidOperationException("Exactly four mouth renderers required");jaw=Mouth.Select(r=>r.sharedMesh.GetBlendShapeIndex("jawOpen_A")).ToArray();seal=Mouth.Select(r=>r.sharedMesh.GetBlendShapeIndex("mouthSeal")).ToArray();if(jaw.Any(i=>i<0)||seal[0]<0||seal[1]<0)throw new InvalidOperationException("Basic mouth binding missing");}
  void LateUpdate(){OpenA=Mathf.Clamp01(OpenA);Seal=Mathf.Clamp01(Seal);Context.GradedField=true;for(int i=0;i<Mouth.Length;i++){Mouth[i].SetBlendShapeWeight(jaw[i],OpenA*100);if(seal[i]>=0)Mouth[i].SetBlendShapeWeight(seal[i],Seal*(1-OpenA)*100);}Mouth[0].sharedMaterials[0].SetFloat("_ClosedWeight",ClosedWeight);}
  [Serializable] class RendererReadback{public string renderer,mesh;public Vector3 localScale;public Bounds localBounds;public float[] localToWorld;public string[] shapes,materials,shaders,baseMaps,shadowMaps,closedBaseMaps,closedShadowMaps;public Vector4[] baseMapST;public bool originalRendererEnabled;public float[] weights,sourceLocalToWorld;}
  [Serializable] class Record{public string file,sha256,pose;public int renderedFrame;public float[] faceFrameLocalToWorld;public float openA,seal,effectiveSeal,closedMapWeight;public RendererReadback[] renderers;public Vector3 cameraPosition;public bool gradedForehead,irisPigment,lowerReturn,directionalHair;}
  [Serializable] class Evidence{public string status="ACTUAL_GPU_BASIC_A_SEAL_STUDY_NOT_FULL_SPEECH_OR_ART_ACCEPTANCE",importAuditSha256,runtimeSha256,builderSha256,unityVersion,graphicsApi;public Record[] captures;public string limitation="Only four saved scale10000 position assets, under identity children with inverse scale.0001. Old rejected eyes are excluded. Head/wall seal=s*(1-a), A=a on all four, no sum normalization.99 tiny head rows remain zeroed below2e-6 native tolerance. Normal/tangent deltas remain historical diagnostic data. New eyes and return are neutral-only. No full speech/emotion/shared female rig acceptance.";}
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-renDesignerMouthCapture");if(i<0||i+1>=args.Length)yield break;var output=Path.GetFullPath(args[i+1]);Directory.CreateDirectory(output);var routine=Capture(output);while(true){object next;try{if(!routine.MoveNext())break;next=routine.Current;}catch(Exception e){File.WriteAllText(Path.Combine(output,"failure.txt"),e.ToString());Debug.LogException(e);Application.Quit(2);yield break;}yield return next;}}
  IEnumerator Capture(string output)
  {
   var review=Context.Context.Review;var records=new List<Record>();var values=new[]{0f,.25f,.5f,.75f,1f,0f};
   foreach(var view in new[]{"front","quarter","profile"})
   {
    review.SourceCamera=false;review.Yaw=view=="quarter"?45:view=="profile"?90:0;review.LightMode=1;review.Lit=true;review.ShowHair=review.ShowCap=true;
    for(int pose=0;pose<values.Length;pose++)
    {
     OpenA=values[pose];Seal=1;for(int frame=0;frame<16;frame++)yield return null;Validate();var file=(pose==5?"return-rest":"a"+Mathf.RoundToInt(OpenA*100).ToString("000"))+"--"+view+".png";Render(Path.Combine(output,file));records.Add(new Record{file=file,sha256=Hash(Path.Combine(output,file)),pose=view,renderedFrame=Time.frameCount,faceFrameLocalToWorld=Enumerable.Range(0,16).Select(k=>review.FaceFrame.localToWorldMatrix[k/4,k%4]).ToArray(),openA=OpenA,seal=Seal,effectiveSeal=Seal*(1-OpenA),closedMapWeight=Mouth[0].sharedMaterials[0].GetFloat("_ClosedWeight"),cameraPosition=review.ModelCamera.transform.position,gradedForehead=Context.GradedField,irisPigment=Context.Context.IrisPigment,lowerReturn=Context.Context.LowerReturn,directionalHair=Context.Context.DirectionalHair,renderers=Mouth.Select(r=>new RendererReadback{renderer=r.name,mesh=r.sharedMesh.name,localScale=r.transform.localScale,localBounds=r.localBounds,localToWorld=Enumerable.Range(0,16).Select(k=>r.localToWorldMatrix[k/4,k%4]).ToArray(),shapes=Enumerable.Range(0,r.sharedMesh.blendShapeCount).Select(r.sharedMesh.GetBlendShapeName).ToArray(),weights=Enumerable.Range(0,r.sharedMesh.blendShapeCount).Select(r.GetBlendShapeWeight).ToArray(),materials=r.sharedMaterials.Select(m=>m.name).ToArray(),shaders=r.sharedMaterials.Select(m=>m.shader.name).ToArray(),baseMaps=r.sharedMaterials.Select(m=>Tex(m,"_BaseMap")).ToArray(),shadowMaps=r.sharedMaterials.Select(m=>Tex(m,"_ShadowMap")).ToArray(),closedBaseMaps=r.sharedMaterials.Select(m=>Tex(m,"_ClosedBaseMap")).ToArray(),closedShadowMaps=r.sharedMaterials.Select(m=>Tex(m,"_ClosedShadowMap")).ToArray(),baseMapST=r.sharedMaterials.Select(m=>m.HasProperty("_BaseMap_ST")?m.GetVector("_BaseMap_ST"):new Vector4(1,1,0,0)).ToArray(),originalRendererEnabled=r.transform.parent.GetComponent<Renderer>().enabled,sourceLocalToWorld=Enumerable.Range(0,16).Select(k=>r.transform.parent.localToWorldMatrix[k/4,k%4]).ToArray()}).ToArray()});
    }
   }
   File.WriteAllText(Path.Combine(output,"MouthLiveEvidence.json"),JsonUtility.ToJson(new Evidence{importAuditSha256=ImportAuditSha256,runtimeSha256=RuntimeSha256,builderSha256=BuilderSha256,unityVersion=Application.unityVersion,graphicsApi=SystemInfo.graphicsDeviceType.ToString(),captures=records.ToArray()},true));Debug.Log("REN_DESIGNER_MOUTH_CAPTURE_OK: "+output);Application.Quit(0);
  }
  void Validate(){var review=Context.Context.Review;if(review.ModelCamera.rect!=new Rect(0,0,1,1)||review.ModelCamera.orthographic||Vector3.Distance(review.ModelCamera.transform.position,review.Target+Quaternion.Euler(0,review.Yaw,0)*(Vector3.forward*review.Distance))>.0001f)throw new InvalidOperationException("Camera initialization/pose mismatch");for(int i=0;i<4;i++){var r=Mouth[i];if(!r.enabled||r.transform.parent.GetComponent<Renderer>().enabled||r.bones.Length!=0||r.transform.localPosition!=Vector3.zero||r.transform.localRotation!=Quaternion.identity||r.transform.localScale!=Vector3.one*.0001f||r.GetBlendShapeWeight(jaw[i])!=OpenA*100||(seal[i]>=0&&r.GetBlendShapeWeight(seal[i])!=Seal*(1-OpenA)*100))throw new InvalidOperationException("Actual mouth transform/weight mismatch: "+r.name);}if(Mouth[0].sharedMaterials[0].GetFloat("_ClosedWeight")!=ClosedWeight)throw new InvalidOperationException("Closed/open pigment endpoint mismatch");}
  void Render(string path){var camera=Context.Context.Review.ModelCamera;var rt=RenderTexture.GetTemporary(1536,1536,24,RenderTextureFormat.ARGB32);var prior=camera.targetTexture;var active=RenderTexture.active;try{camera.targetTexture=rt;RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());Destroy(image);}finally{camera.targetTexture=prior;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);}}
  void OnGUI(){var prior=GUI.matrix;GUI.matrix=Matrix4x4.Scale(Vector3.one*Mathf.Min(Screen.width/1600f,Screen.height/900f));GUI.Box(new Rect(25,839,710,59),GUIContent.none);GUI.Label(new Rect(35,842,125,25),"Basic A mouth");OpenA=GUI.HorizontalSlider(new Rect(155,850,175,20),OpenA,0,1);GUI.Label(new Rect(350,842,60,25),"Seal");Seal=GUI.HorizontalSlider(new Rect(410,850,175,20),Seal,0,1);if(GUI.Button(new Rect(610,844,110,28),"Closed rest")){OpenA=0;Seal=1;}GUI.Label(new Rect(35,874,680,22),"A/seal construction controls only. Eyes remain neutral; full speech and likeness unapproved.");GUI.matrix=prior;}
  static string Tex(Material m,string property)=>m.HasProperty(property)&&m.GetTexture(property)?m.GetTexture(property).name:null;
  static string Hash(string p){using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
 }
}
